/* From Uiverse.io by vinodjangid07  - Tags: icon, animation, button, custom, hover effect */
.__UIV_SCOPE__ .palette-button {
  background-color: #fff;
  width: 170px;
  height: 55px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-size: 16px;
  font-weight: 600;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  box-shadow: 0px 0px 10px rgb(196, 196, 196);
  transition: all 0.3s;
}
.__UIV_SCOPE__ .palette {
  width: 30px;
  transition: all 0.3s;
}
.__UIV_SCOPE__ .palette-button:hover .palette {
  transform: rotate(-45deg);
}
.__UIV_SCOPE__ .palette path {
  fill: rgb(255, 163, 183);
  stroke-width: 0;
}
.__UIV_SCOPE__ .drop1 {
  fill: rgb(115, 115, 255);
  stroke-width: 0;
}
.__UIV_SCOPE__ .drop2 {
  fill: red;
  stroke-width: 0;
}
.__UIV_SCOPE__ .drop3 {
  fill: yellow;
  stroke-width: 0;
}
.__UIV_SCOPE__ .drop4 {
  fill: rgb(104, 255, 255);
  stroke-width: 0;
}
.__UIV_SCOPE__ .palette-button:hover {
  transform: scale(1.05);
  background-color: rgb(176, 115, 255);
  color: white;
}
